import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/BigBaron.html","title":"BigBaron","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.72,"words":515},"filePathRelative":"BigBaron.md"}`),a={name:`BigBaron.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="bigbaron" tabindex="-1"><a class="header-anchor" href="#bigbaron"><span>BigBaron</span></a></h1><p>JSの<a href="./サーフボード.html">サーフボード</a>。JS Big Baron。</p><p>パフォーマンスよりのミッドレングス。ツイン。</p><h2 id="購入したスペック" tabindex="-1"><a class="header-anchor" href="#購入したスペック"><span>購入したスペック</span></a></h2><ul><li>長さ： 6’8”(203.2cm)</li><li>幅： 20 3/4”(52.71cm)</li><li>厚み：2 5/8”(6.67cm)</li><li>容積：38.5CL</li><li>フィンタイプ：FCS2 Twin</li><li>PE</li><li><a href="https://www.jsindustries.jp/products/big-baron?variant=48969857663272" target="_blank" rel="noopener noreferrer">JS-ビックバロン – JS Industries Japan</a></li></ul><p>PEというのは良く知らないがJSのページを見た感じPU+EPSみたいな何かで、ビッグバロンの中では一番PUよりのものっぽい（PUと呼んでいる人も多い）。</p><h3 id="購入-2026-10-02-金" tabindex="-1"><a class="header-anchor" href="#購入-2026-10-02-金"><span>購入 2026-10-02 (金)</span></a></h3><p>メルカリで6万5000円で購入。</p><h2 id="何回か乗った感想-2026-10-20-火" tabindex="-1"><a class="header-anchor" href="#何回か乗った感想-2026-10-20-火"><span>何回か乗った感想 2026-10-20 (火)</span></a></h2><p>腹くらいのたるめの波では最高だ。めちゃ楽しい。凄く良い買い物をした。</p><p>事前には重さが足りるかな？と不安もあったが、テイクオフとか一度勢いがつけば重さを感じられるシーンは多く、割と満足している。 オフショアでも煽られない。</p><p>オンショアは向いていないと言われがちだし、ゲットが辛いけれど、乗ればミッドが良いケースもある。 基本的には長く乗れないと苦手で、長く乗れればオンショアでも良い。 たぶんショアブレイクの掘れる早い奴は駄目なんだろうが、駄目なのはそれくらいじゃないかな？ オンショアですぐ波が終わっちゃうケースはそもそもショートでも立つだけだからなぁ。</p><p>結局ミッドでは駄目なケースの方がむしろ少なくて、 ほとんどのケースでミッドで行ける。 youtubeとかでは気分の問題で使い分ける、というのを見かけるが、その気持が分かるな。 行けるかと言われればほとんど全部行けるが、 ミッドをやりたい気分なのか？という方がむしろ出番かどうかを分ける判断基準になる。</p><p>テイクオフの性能は極めて高くてショートとは全然別物だが、取り回しは結構良くてロングとも全然違う。 自転車で持っていくのとかでも全然楽で、これは結構大きいなぁ、と思った。 ロングはトレーラーみたいなキャリアじゃないとチャリは無理だ。 ロングでもショートでも無い何かだな。</p><p>取り回しについて。波の前でUターンしたりとかが楽で、ロングよりもショートのテイクオフの練習になる。ロングは別の技術という感じで、ショートの練習には微妙なんだよな。 別のものとして楽しむなら悪くは無いんだろうが。</p><p>動きについて。大きく動かすには全く問題が無い。乗ってすぐに動かせる。ロングはなかなか動かせず苦戦したのとは好対照。 たまにコケる事はあってやはりある程度上手くなったらミッド的な乗り方を意識する方がいいのだろうけれど。 カットバックの練習にはちょうどいい。 ちょっとしたローラーコースターやリップもやれているが、こちらは本番というよりはショートの練習という感じがしている。</p><p>カーブはショートのようにいい感じは出来ていない。これはカットバック優先で練習しているからやってみていないというのもある。</p><p>あまり掘れた所で当てに行ったりとかはしていない。youtubeを見ている感じだとそれも出来るっぽいのだけれど、 現時点ではミッドレングスっぽく大きく動かす感じを意識してやっている。</p><p>テイクオフが簡単なのでテイクオフより先の練習をたくさん出来る。 またテイクオフもショートで本当はこういう感じに乗りたい、という、 上手い人のテイクオフの体験というか正解の体験みたいなのが積みやすい良さはある。 ただショートの方が明らかに難しく、ショートでの練習は必要だよなぁ、とは思う。</p><p>ボトムターンとかで変に上半身を動かしすぎるのを直したいと思ってミッドレングスを試している所もあり、 これにはいい練習になっている。変な動きをしているケースが自覚出来て、たくさん練習出来るので上達も早い気はする（まだ上達はしてないが）。 やはり練習出来る本数が増える、というのは重要だよなぁ。</p><p>という事で今の所、ビッグバロンは凄く良いね。気に入っている。</p><h3 id="事前調査" tabindex="-1"><a class="header-anchor" href="#事前調査"><span>事前調査</span></a></h3><p>ミッドレングス欲しいな〜とメルカリを見ていたら出ていたので、どんなボードなのか調べてみる。 割とパフォーマンス寄りのミッドレングス、って感じみたい。</p><p>前大原ヒロトプロが乗っていた奴だな。</p><ul><li><a href="https://www.youtube.com/watch?v=uj0CkPYOWTA" target="_blank" rel="noopener noreferrer">ムラサキスポーツ鵠沼店に潜入してみた！（驚きのボードを発見！） - YouTube</a></li><li><a href="https://www.youtube.com/watch?v=fNsKc4mAKCI" target="_blank" rel="noopener noreferrer">【脅威的な長さチェンジ】胸肩の波でJSミッドレングス乗り比べしたらめちゃめちゃ楽しすぎた！！ - YouTube</a></li></ul><p>ヒロトプロは全体的にめっちゃショートっぽく乗る。</p><p>一本目の動画ではめっちゃオンショアでぐちゃぐちゃ系の波だが良く走っているのでオンショアには強そう。</p><p>二本めの動画は、大きめの波だとテールが抜けてコケる事が多そう。この辺はツインの欠点もありそうか。 でもこういうコンディションで乗りたい訳でも無いからな。</p><p>以下の動画は小波が多く、オンショアのヒザくらいでも割と走ってて、いい意味で重さもありそう。自分が使いたいコンディションにも似ていて参考になる。 たるい所も走っているように見える。</p><ul><li><a href="https://www.youtube.com/watch?v=AqSqsjUuruM" target="_blank" rel="noopener noreferrer">【人気のミッドレングスシリーズ】JS industries - BIGBARON【ビッグバロン】 - YouTube</a></li></ul><p>以下の動画ではオンショアでもオフショアでも乗っている。オフショアはすこし波が良すぎるが、オフショアでも降りていきそうな雰囲気はある。</p><ul><li><a href="https://www.youtube.com/watch?v=atGew3OpboE&amp;t=356s" target="_blank" rel="noopener noreferrer">地球上で断然最高のミッドレングス JS ビッグバロン レビュー - WOOLY TV #25 - YouTube</a></li></ul><p>動かせるのはいいとして、ミッドレングスに求めるものがあるか、というのを確認したいが、以下の動画は結構いまいちな波でかなりテイクオフが早いのが分かる。</p><ul><li><a href="https://www.youtube.com/watch?v=L6SEm75Yswc" target="_blank" rel="noopener noreferrer">Average Surfer Rides a 6&#39;8 JS Big Baron on a Sunny Southern California Day - YouTube</a></li></ul><p>こんなにサクサク乗れるならいいかもしれない。</p><p>Redditではベコベコになる、と言っている人がたまにいるが人によるっぽい。</p><p><a href="https://www.reddit.com/r/surfing/comments/1438p2v/js_big_baron_anybody/" target="_blank" rel="noopener noreferrer">JS Big Baron, anybody? : r/surfing</a></p>`,37)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};